#[derive(Debug, Clone, PartialEq, Eq)] pub enum FileCommand { Cd(String), Mkdir(String), Touch(String), Rename(String,String), DownloadSelected, Upload(String), Chmod(String,String), Chown(String,String), Open, Edit, CopyPath, BookmarkAdd(String), BookmarkJump(String), Unknown(String) }
pub fn parse_command(input:&str)->FileCommand{ let parts=shell_words::split(input.trim_start_matches(':')).unwrap_or_default(); match parts.as_slice(){ [cmd,path] if cmd=="cd"=>FileCommand::Cd(path.clone()), [cmd,path] if cmd=="mkdir"=>FileCommand::Mkdir(path.clone()), [cmd,path] if cmd=="touch"=>FileCommand::Touch(path.clone()), [cmd,old,new] if cmd=="rename"=>FileCommand::Rename(old.clone(),new.clone()), [cmd,sel] if cmd=="download" && sel=="selected"=>FileCommand::DownloadSelected, [cmd,path] if cmd=="upload"=>FileCommand::Upload(path.clone()), [cmd,mode,path] if cmd=="chmod"=>FileCommand::Chmod(mode.clone(),path.clone()), [cmd,owner,path] if cmd=="chown"=>FileCommand::Chown(owner.clone(),path.clone()), [cmd] if cmd=="open"=>FileCommand::Open, [cmd] if cmd=="edit"=>FileCommand::Edit, [cmd] if cmd=="copy-path"=>FileCommand::CopyPath, [a,b,c] if a=="bookmark" && b=="add"=>FileCommand::BookmarkAdd(c.clone()), [a,b,c] if a=="bookmark" && b=="jump"=>FileCommand::BookmarkJump(c.clone()), _=>FileCommand::Unknown(input.into()) } }
